// Build the model request. BYTE-IDENTICAL to the Python reference's
// build_user_prompt() -- see workflows/build_request.js and D26. The
// prompt hash plus this string IS the call.
const inputs = $('Inputs').first().json;
const prompt = $('Prompt registry').all();
const handoffs = $('Handoff registry').all();
const contract = $('Contract registry').all();

if (prompt.length === 0) {
  throw new Error(`PromptMissing: no active prompt for ${inputs.ENGINE_ID}. RUN_ENGINE will not fall back to a stub.`);
}
if (handoffs.length === 0) {
  throw new Error(`HandoffMissing: no handoff registered for ${inputs.ENGINE_ID}/${inputs.MODE}. RUN_ENGINE will not treat a run as successful without knowing what reasoning it was supposed to produce.`);
}
if (contract.length === 0) {
  throw new Error('ContractMissing: no active control contract. RUN_ENGINE will not validate a control block against nothing.');
}

const ENVELOPE_TAG = 'RUNTIME_INVOCATION';
const expected = handoffs.map((h) => ({ tag: h.json.tag, required: h.json.required }));

// Key order is part of the byte contract.
const envelope = {
  ENGINE: inputs.ENGINE_ID,
  MODE: inputs.MODE,
  PASS: inputs.PASS || 'SINGLE',
  EXPECTED_HANDOFF_BLOCKS: expected.map((h) => h.tag),
  REQUIRED_HANDOFF_BLOCKS: expected.filter((h) => h.required).map((h) => h.tag),
  CONTROL_BLOCK_REQUIRED: true,
};

const canonicalJson = (v) => JSON.stringify(v, null, 2);
const userPrompt = `<${ENVELOPE_TAG}>\n${canonicalJson(envelope)}\n</${ENVELOPE_TAG}>\n\n${canonicalJson(inputs.STRUCTURED_INPUT)}`;

return [{ json: {
  run_id: crypto.randomUUID(),
  system_prompt: prompt[0].json.content,
  prompt_file: prompt[0].json.prompt_file,
  prompt_hash: prompt[0].json.prompt_hash,
  user_prompt: userPrompt,
  expected_handoffs: expected,
  contract: contract[0].json.document,
  attempt: 1,
  totals: { input_tokens: 0, output_tokens: 0, duration_ms: 0 },
} }];

// The provider call, WITH THE SAME TRANSPORT RETRY as the reference.
//
// This was an httpRequest node configured with six retries at a fixed
// 2000 ms while its own note described exponential backoff. Python does
// exponential + jitter + Retry-After, and the difference matters most
// exactly where it is least visible: Step 16's Knowledge Factory, at
// KNOWLEDGE_MAX_CONCURRENCY 3, on a 2 vCPU box. Fixed-interval retries
// from concurrent workers return at the same instant and re-overload a
// provider that is already shedding load.
//
// So the call is made here rather than by the HTTP node, because n8n's
// retry cannot express these semantics. Mirrors _call_provider().
//
// IT USES helpers.httpRequest, NOT fetch. The Code node runs inside vm2,
// whose sandbox has no `fetch` and no `URL` -- verified empirically
// against the installed vm2, on 2.11.4 and on 2.35.7 alike. It does have
// setTimeout, Promise, Math, Date, JSON and `helpers`. A draft written
// with fetch passed every test and could never have run, because the test
// harness ran the extracted source in plain Node where fetch is global
// (D33).
//
// The options below are n8n-core 2.11.1's httpRequest contract:
//   returnFullResponse    -> { body, headers, statusCode, statusMessage }
//   ignoreHttpStatusErrors -> validateStatus = () => true, so a 4xx/5xx
//                             RETURNS rather than throwing, which is what
//                             lets this loop see the status and decide
// A network-level failure still throws, and is retryable, as in Python.
const build = $('Build request').first().json;

const MAX_TRANSPORT_ATTEMPTS = Number($env.LLM_TRANSPORT_MAX_ATTEMPTS || 6);
const BACKOFF_BASE = Number($env.LLM_TRANSPORT_BACKOFF_BASE || 2);
const BACKOFF_CAP = 60;
// A 503 or 429 means the same request will very likely succeed shortly. A
// 400 or 401 means it will not, ever -- retrying that spends wall-clock
// and, on a metered endpoint, money. Anything unrecognised is permanent:
// a retry loop that fires on unknown errors is how a bad request becomes
// a bill.
const RETRYABLE = new Set([408, 409, 425, 429, 500, 502, 503, 504]);
// The thrown half of the same rule. Python retries URLError, TimeoutError
// and ConnectionError and NOTHING else -- a NameError there is permanent
// and surfaces on the first attempt. Without this list every thrown error
// looked like a network failure, so a ReferenceError in this very node was
// retried five times with exponential backoff and then dead-lettered as a
// transport problem. A programming error must fail once, loudly.
const NETWORK_CODES = new Set([
  'ECONNREFUSED', 'ECONNRESET', 'ETIMEDOUT', 'ECONNABORTED', 'ENOTFOUND',
  'EAI_AGAIN', 'EPIPE', 'EHOSTUNREACH', 'ENETUNREACH', 'ERR_NETWORK',
  'ERR_SOCKET_CONNECTION_TIMEOUT',
]);

const sleep = (seconds) => new Promise((r) => setTimeout(r, seconds * 1000));

function retryAfterSeconds(headers) {
  // Only the delta-seconds form, as in the reference. The HTTP-date form
  // is legal but needs clock-skew handling to be safe, and an unparseable
  // value falls back to our own backoff rather than to zero.
  //
  // Case-insensitive: axios lowercases response header names, so this
  // arrives as 'retry-after', not 'Retry-After'.
  if (!headers) return null;
  let raw = null;
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === 'retry-after') { raw = headers[key]; break; }
  }
  const value = Number.parseFloat(raw);
  return Number.isFinite(value) ? Math.max(0, value) : null;
}

const url = `${String($env.LLM_BASE_URL || '').replace(/\/$/, '')}/chat/completions`;
const body = {
  model: build.model_name,
  messages: [
    { role: 'system', content: build.system_prompt },
    { role: 'user', content: build.user_prompt },
  ],
  temperature: 0.2,
};

// Every PHYSICAL attempt is recorded, failures included: a retry invisible
// in the cost table makes the measurement understate what a call really
// costs, and D5 is a decision made on those numbers.
const attempts = [];
let lastError = null;
let payload = null;
let durationMs = 0;

for (let attempt = 1; attempt <= MAX_TRANSPORT_ATTEMPTS; attempt += 1) {
  const started = Date.now();
  let response = null;
  let failure = null;
  try {
    response = await helpers.httpRequest({
      method: 'POST',
      url,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${$env.LLM_API_KEY}` },
      body,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (response.statusCode < 200 || response.statusCode >= 300) {
      failure = { status: response.statusCode, headers: response.headers, name: `HTTPError${response.statusCode}` };
    }
  } catch (err) {
    // Network-level: DNS, connection refused, timeout. Retryable, as in
    // the reference, which treats URLError/TimeoutError/ConnectionError
    // the same way -- and ONLY those. Anything without a network code is
    // this code being wrong, not the network being down.
    const code = err.code || (err.cause && err.cause.code) || null;
    failure = { status: null, headers: null, code,
                name: err.name || 'NetworkError',
                retryable: NETWORK_CODES.has(code) };
  }

  const elapsed = Date.now() - started;

  if (failure === null) {
    payload = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
    durationMs = elapsed;
    attempts.push({ ok: true, ms: elapsed, error_class: null });
    break;
  }

  attempts.push({ ok: false, ms: elapsed, error_class: failure.name });
  lastError = failure;

  const retryable = failure.status === null
    ? failure.retryable === true
    : RETRYABLE.has(failure.status);
  if (!retryable || attempt === MAX_TRANSPORT_ATTEMPTS) break;

  // Exponential, capped, jittered so concurrent knowledge-batch calls do
  // not all return at the same instant. A Retry-After from the provider
  // wins: it knows when it will be back and we do not.
  let delay = Math.min(BACKOFF_CAP, BACKOFF_BASE ** attempt);
  delay *= 0.5 + Math.random();
  const asked = retryAfterSeconds(failure.headers);
  await sleep(Math.min(BACKOFF_CAP, asked === null ? delay : asked));
}

return [{ json: {
  provider_failed: payload === null,
  error_class: payload === null ? (lastError ? lastError.name : 'NoResponse') : null,
  transport_attempts: attempts,
  duration_ms: durationMs,
  ...(payload || { choices: [], usage: {} }),
} }];

// Parse the response into THREE separate things (D24): human output,
// substantive handoff, control block. They are never interchangeable.
const build = $('Build request').first().json;
const payload = $json;
const choice = (payload.choices || [])[0] || {};
// content is ABSENT, not empty, when a reasoning model spends its whole
// budget thinking. Return '' and fail honestly at extraction.
const raw = (choice.message || {}).content || '';
const usage = payload.usage || {};
const promptTokens = usage.prompt_tokens || 0;
// REASONING TOKENS ARE BILLED AS OUTPUT AND ARE NOT IN completion_tokens.
const billedOutput = Math.max(usage.completion_tokens || 0, (usage.total_tokens || 0) - promptTokens);

const CONTROL_TAG = 'CONTROL_BLOCK';
const HANDOFF_KEY = /^([A-Z][A-Z0-9_]{2,}):[ \t]*(.*)$/;

function parseHandoffBlock(body) {
  const fields = {}; const order = []; const preamble = [];
  let current = null;
  for (const line of body.split('\n')) {
    const m = HANDOFF_KEY.exec(line);
    if (m) {
      current = m[1];
      const first = m[2].trim();
      if (current in fields) fields[current] = `${fields[current]}\n${first}`.trim();
      else { fields[current] = first; order.push(current); }
      continue;
    }
    if (current === null) { if (line.trim()) preamble.push(line); continue; }
    fields[current] = fields[current] ? `${fields[current]}\n${line}`.trim() : line.trim();
  }
  fields._field_order = order;
  fields._raw = body;
  if (preamble.length) fields._preamble = preamble.join('\n');
  return fields;
}

function extractBlock(text, tag) {
  const open = `<${tag}>`; const close = `</${tag}>`;
  if (!text.includes(open) || !text.includes(close)) return null;
  let body = text.split(open)[1].split(close)[0];
  const stripped = body.trim();
  if (stripped.startsWith('```')) body = stripped.split('\n').slice(1).join('\n').replace(/```$/, '');
  return body;
}

let control = null;
const controlBody = extractBlock(raw, CONTROL_TAG);
if (controlBody !== null) { try { control = JSON.parse(controlBody.trim()); } catch (e) { control = null; } }
if (control !== null && typeof control !== 'object') control = null;

const handoffs = {};
for (const h of build.expected_handoffs) {
  const body = extractBlock(raw, h.tag);
  if (body === null) continue;
  const parsed = parseHandoffBlock(body);
  if (Object.keys(parsed).filter((k) => !k.startsWith('_')).length === 0) continue;
  handoffs[h.tag] = parsed;
}

const errors = [];
if (control === null) errors.push(`no parseable <${CONTROL_TAG}> block in response`);
for (const h of build.expected_handoffs) {
  if (h.required && !(h.tag in handoffs)) {
    errors.push(`no parseable <${h.tag}> block in response. The control block routes; this is the reasoning the next engine needs, and a response without it is not a completed run.`);
  }
}

// The human report is what precedes the FIRST machine block, whichever
// that is -- not just the control tag, or every handoff would land in it.
const boundaries = [CONTROL_TAG, ...build.expected_handoffs.map((h) => h.tag)]
  .map((t) => raw.indexOf(`<${t}>`)).filter((i) => i >= 0);
const first = boundaries.length ? Math.min(...boundaries) : -1;
const humanOutput = (first >= 0 ? raw.slice(0, first) : raw).trim();

const primaryTag = (build.expected_handoffs.find((h) => h.required && h.tag in handoffs)
  || { tag: Object.keys(handoffs)[0] }).tag || null;
const secondary = {};
for (const [tag, body] of Object.entries(handoffs)) if (tag !== primaryTag) secondary[tag] = body;

return [{ json: {
  raw,
  control,
  handoffs,
  errors,
  human_output: humanOutput,
  structured: primaryTag ? handoffs[primaryTag] : {},
  primary_tag: primaryTag,
  secondary_handoffs: secondary,
  input_tokens: promptTokens,
  output_tokens: billedOutput,
} }];

// Validate the control block against the STORED contract with ajv --
// the same document the Python reference hands to jsonschema.
// NODE_FUNCTION_ALLOW_EXTERNAL must include ajv,ajv-formats.
//
// The MESSAGE WORDING is ours, not ajv's (D26). This string is persisted
// to engine_runs.error_detail and is what the repair prompt sends the
// model on attempt two; ajv and jsonschema phrase the same violation
// differently, so both build the shared format from their own library's
// structured error data instead.
const Ajv = require('ajv/dist/2020');
const addFormats = require('ajv-formats');
const build = $('Build request').first().json;
const parsed = $json;

const typeNames = (v) => (Array.isArray(v)
  ? v.map(String).sort().join(', ')
  : String(v));

function formatViolation(field, keyword, detail) {
  let reason;
  if (keyword === 'required') reason = 'required property missing';
  else if (keyword === 'enum') reason = 'not one of ' + detail.map(String).sort().join(', ');
  else if (keyword === 'type') reason = `expected type ${typeNames(detail)}`;
  else if (keyword === 'const') reason = `must be ${JSON.stringify(detail)}`;
  else if (keyword === 'minLength') reason = detail === 1 ? 'must not be empty' : `shorter than ${detail} characters`;
  else if (keyword === 'additionalProperties') reason = 'not permitted by the contract';
  else reason = String(keyword);
  return `${field}: ${reason}`;
}

let errors = [...parsed.errors];
if (parsed.control !== null) {
  const ajv = new Ajv({ allErrors: true, strict: false });
  addFormats(ajv);
  const validate = ajv.compile(build.contract);
  if (!validate(parsed.control)) {
    const CONTAINERS = new Set(['if', 'then', 'else', 'allOf', 'anyOf', 'oneOf', 'not']);
    for (const e of validate.errors || []) {
      if (CONTAINERS.has(e.keyword)) continue;
      let field; let detail;
      if (e.keyword === 'required') { field = e.params.missingProperty; detail = null; }
      else if (e.keyword === 'additionalProperties') { field = e.params.additionalProperty; detail = null; }
      else {
        field = (e.instancePath || '').replace(/^\//, '').split('/')[0] || '(root)';
        if (e.keyword === 'enum') detail = e.params.allowedValues;
        else if (e.keyword === 'type') detail = e.params.type;
        else if (e.keyword === 'const') detail = e.params.allowedValue;
        else if (e.keyword === 'minLength') detail = e.params.limit;
        else detail = null;
      }
      errors.push(formatViolation(field, e.keyword, detail));
    }
  }
}
errors = [...new Set(errors)].sort();

return [{ json: { ...parsed, errors, valid: errors.length === 0 } }];

