SELECT set_client_scope(($1::jsonb #>> '{}')::uuid);
UPDATE engine_runs SET status='SUCCEEDED', attempts=($2::jsonb #>> '{}')::int, completed_at=now(), input_tokens=($3::jsonb #>> '{}')::int, output_tokens=($4::jsonb #>> '{}')::int, duration_ms=($5::jsonb #>> '{}')::int WHERE run_id=($6::jsonb #>> '{}')::uuid;
INSERT INTO engine_outputs (run_id, human_output, structured, control, schema_valid, handoff_tag, handoff_mode, secondary_handoffs) VALUES (($6::jsonb #>> '{}')::uuid, ($7::jsonb #>> '{}'), $8::jsonb, $9::jsonb, true, ($10::jsonb #>> '{}'), ($11::jsonb #>> '{}'), $12::jsonb)

SELECT set_client_scope(($1::jsonb #>> '{}')::uuid);
UPDATE engine_runs SET status='DEAD_LETTER', attempts=($2::jsonb #>> '{}')::int, completed_at=now(), input_tokens=($3::jsonb #>> '{}')::int, output_tokens=($4::jsonb #>> '{}')::int, duration_ms=($5::jsonb #>> '{}')::int, error_class=($6::jsonb #>> '{}'), error_detail=($7::jsonb #>> '{}') WHERE run_id=($8::jsonb #>> '{}')::uuid;
INSERT INTO dead_letter_jobs (job_type, entity_type, entity_id, client_id, failure_reason, raw_payload, attempts) VALUES (($9::jsonb #>> '{}'), 'engine_run', ($8::jsonb #>> '{}'), ($1::jsonb #>> '{}')::uuid, ($7::jsonb #>> '{}'), $10::jsonb, ($2::jsonb #>> '{}')::int)

