// The normalized result the caller receives, matching EngineResult.
const parsed = $json;
const build = $('Build request').first().json;
const succeeded = parsed.valid === true;
return [{ json: {
  run_id: build.run_id,
  status: succeeded ? 'SUCCEEDED' : 'DEAD_LETTER',
  control: succeeded ? parsed.control : null,
  human_output: succeeded ? parsed.human_output : parsed.raw,
  structured: succeeded ? parsed.structured : null,
  handoff_tag: succeeded ? parsed.primary_tag : null,
  handoff_mode: $('Inputs').first().json.MODE,
  secondary_handoffs: succeeded ? parsed.secondary_handoffs : {},
  attempts: build.attempt,
  error: succeeded ? null : parsed.errors.join('; '),
} }];
